function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
const t=(...a)=>a[langs.indexOf(lang)],name=q=>q.names[langs.indexOf(lang)];
function start(){const pool=mode==='flags'?shuffle(flags):mode==='animals'?shuffle(animals):shuffle([...shuffle(flags).slice(0,3),...shuffle(animals).slice(0,2)]);round=pool.slice(0,5).map(q=>({...q,options:q.type==='flag'?shuffle([q,...shuffle(flags.filter(f=>f.id!==q.id)).slice(0,3)]).map(f=>f.id):shuffle([q.region,...shuffle(regions.map((_,i)=>i).filter(i=>i!==q.region)).slice(0,3)])}));pos=0;reset();render()}
function reset(){solved=false;hinted=false;wrong.clear()}
function render(){const q=round[pos];$('#progress').innerHTML=round.map((_,i)=>`<span class="step ${i<pos?'done':i===pos?'current':''}"></span>`).join('');if(!q){$('#game').innerHTML='<div class="finish"><p class="eyebrow">ЭКСПЕДИЦИЯ ЗАВЕРШЕНА</p><h2>Пять загадок раскрыты!</h2><p>Выбери другую тему или отправляйся в новый раунд.</p><button class="primary" id="again">Ещё пять загадок</button></div>';$('#again').onclick=start;return}
$('#game').innerHTML=`<div class="visual">${q.type==='flag'?`<div class="flag-window"><img class="${hinted||solved?'revealed':''}" src="assets/flags/${q.id}.svg" alt="${solved?name(q):'Фрагмент флага'}"></div>`:`<span class="animal" aria-hidden="true">${q.emoji}</span><strong>${name(q)}</strong>`}${solved?'<div class="result-map" id="map"></div>':`<small>${q.type==='flag'?'Часть флага скрыта. Узнаешь?':'Где живёт в природе, а не в зоопарке?'}</small>`}</div><div class="question"><span class="tag">ЗАГАДКА ${pos+1} / 5</span><h2>${q.type==='flag'?t('Чей это флаг?','Whose flag is this?','De que país é esta bandeira?'):t('Где его родной дом?','Where is its native home?','Onde vive na natureza?')}</h2><div class="choices">${q.options.map(id=>{let correct=q.type==='flag'?id===q.id:id===q.region;return `<button data-answer="${id}" ${solved||wrong.has(id)?'disabled':''} class="${solved&&correct?'correct':''}">${q.type==='flag'?name(flags.find(f=>f.id===id)):regions[id][langs.indexOf(lang)]}${solved&&correct?' ✓':''}</button>`}).join('')}</div><p class="message" role="status">${solved?`<strong>${t('Разгадано!','Solved!','Descoberto!')}</strong> ${q.fact}`:wrong.size?'Пока не совпало. Попробуй другой вариант — спешить не нужно.':hinted?(q.type==='flag'?'Теперь флаг открыт целиком.':q.fact):''}</p><div class="actions">${solved?'<button class="primary" id="next">'+(pos===4?'Завершить раунд':'Следующая загадка →')+'</button>':'<button id="hint">Подсказка</button><button id="reveal">Узнать ответ</button>'}</div></div>`;
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const id=q.type==='flag'?b.dataset.answer:Number(b.dataset.answer);if(id===(q.type==='flag'?q.id:q.region))solved=true;else wrong.add(id);render()});if(solved){$('#next').onclick=()=>{pos++;reset();render()};draw(q)}else{$('#hint').onclick=()=>{hinted=true;render()};$('#reveal').onclick=()=>{solved=true;render()}}
}
function draw(q){const features=topojson.feature(world,world.objects.features).features,p=d3.geoNaturalEarth1().fitExtent([[8,8],[412,225]],{type:'Sphere'}),path=d3.geoPath(p);const svg=d3.select('#map').append('svg').attr('viewBox','0 0 420 240').attr('role','img').attr('aria-label',q.type==='flag'?name(q)+' на карте':'Пример места в регионе обитания');svg.append('path').datum({type:'Sphere'}).attr('d',path).attr('fill','#c7e4eb');svg.selectAll('.land').data(features).join('path').attr('d',path).attr('fill',f=>q.iso&&f.properties.id===q.iso?'#f4b333':'#f6faf6').attr('stroke','#86a5af').attr('stroke-width',.4);if(q.point){let [x,y]=p(q.point);svg.append('circle').attr('cx',x).attr('cy',y).attr('r',6).attr('fill','#ca501b').attr('stroke','white').attr('stroke-width',2)}$('#map').insertAdjacentHTML('beforeend',`<small>${q.type==='flag'?name(q):'Точка — пример места, не весь ареал'}</small>`)}
$('#lang').onchange=e=>{lang=e.target.value;render()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));start()});
start();flags.forEach(f=>{const i=new Image();i.src=`assets/flags/${f.id}.svg`});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_geography_round',description:'Start a fresh five-question geography round and replace the current round.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['mixed','flags','animals']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['mixed','flags','animals'].includes(input.mode))throw Error('Invalid mode');document.querySelector(`[data-mode="${input.mode}"]`).click();return{mode,questions:round.length}}})).catch(()=>{})}catch{}}
